const puff = (g, x, y, r, c, a) => { g.save(); g.globalAlpha = a; disc(g, x, y, r, c); g.restore(); };
const sparkle = (g, x, y, r, c) => { px(g, x - r, y, r * 2 + 1, 1, c); px(g, x, y - r, 1, r * 2 + 1, c); };
function spr(g, n, x, y, w, rot = 0, a = 1, add = false) { const im = IM[n]; if (!im || !im.naturalWidth) return; const h = w * im.naturalHeight / im.naturalWidth; g.save(); g.globalAlpha = a; if (add) g.globalCompositeOperation = 'lighter'; g.translate(Math.round(x), Math.round(y)); if (rot) g.rotate(rot); g.drawImage(im, Math.round(-w / 2), Math.round(-h / 2), Math.round(w), Math.round(h)); g.restore(); }
const tmp = document.createElement('canvas'); tmp.width = 128; tmp.height = 128; const tg = tmp.getContext('2d');
function tint(im, w, h, col, k) { tg.globalCompositeOperation = 'source-over'; tg.globalAlpha = 1; tg.clearRect(0, 0, 128, 128); tg.imageSmoothingEnabled = false; tg.drawImage(im, 0, 0, w, h); tg.globalCompositeOperation = 'source-atop'; tg.globalAlpha = k; tg.fillStyle = col; tg.fillRect(0, 0, w, h); tg.globalCompositeOperation = 'source-over'; tg.globalAlpha = 1; return tmp; }
function tspr(g, n, x, y, w, col, k, rot = 0, a = 1, add = false) { const im = IM[n]; if (!im || !im.naturalWidth) return; const h = Math.round(w * im.naturalHeight / im.naturalWidth), ww = Math.round(w), src = tint(im, ww, h, col, k); g.save(); g.globalAlpha = a; if (add) g.globalCompositeOperation = 'lighter'; g.translate(Math.round(x), Math.round(y)); if (rot) g.rotate(rot); g.drawImage(src, 0, 0, ww, h, Math.round(-ww / 2), Math.round(-h / 2), ww, h); g.restore(); }
const arcP = (p0, p1, h, u) => ({ x: lerp(p0.x, p1.x, u), y: lerp(p0.y, p1.y, u) - 4 * h * u * (1 - u) });
const bolt = (g, x0, y0, x1, y1, seed, amp, c, th = 1) => { let qx = x0, qy = y0; const n = Math.max(3, Math.floor(Math.hypot(x1 - x0, y1 - y0) / 7)); for (let i = 1; i <= n; i++) { const k = i / n, x = lerp(x0, x1, k) + (i < n ? (hash(seed + i * 3.1) - .5) * amp : 0), y = lerp(y0, y1, k) + (i < n ? (hash(seed + i * 7.7) - .5) * amp : 0); line(g, qx, qy, x, y, c, th); qx = x; qy = y; } };
