    const xs = [FXc - 30, FXc + 16, FXc - 6], ta = [.65, 1.0, 1.35];
    for (let i = 0; i < 3; i++) { const d = t - ta[i]; if (d > 0 && t > 0) { const k2 = 1 - ph(t, 1.9, 2.4); g.save(); g.globalAlpha = .8 * k2; fillEll(g, xs[i], GY, 8 + i * 3, 2, '#1a1410'); g.restore(); } if (d > 0 && d < .22 && (sn(t, 24) % 2 === 0 || d < .06)) { const w = 3 + i * 2; bolt(g, xs[i] + 6, 10, xs[i], GY - 2, sn(t, 14) + i * 3, 18, '#c8a010', w + 2); bolt(g, xs[i] + 6, 10, xs[i], GY - 2, sn(t, 14) + i * 3, 18, '#fff27a', w); bolt(g, xs[i] + 6, 10, xs[i], GY - 2, sn(t, 14) + i * 3, 18, '#fff', Math.max(1, w - 3)); spr(g, 'lightning', xs[i], 48, 34 + i * 12, 0, .95, true); halo(g, xs[i], GY - 4, 22 + i * 8, '#fff27a', 1 - d * 3); flash(g, t, ta[i], ta[i] + .1, '#fff6a0', .3 + i * .15); } if (d > 0) { ring(g, xs[i], GY - 1, ph(t, ta[i], ta[i] + .5), '#fff', '#fff27a', 30 + i * 12); sparks(g, xs[i], GY - 8, ph(t, ta[i], ta[i] + .45), '#fff', '#ffe84d', 8, 22 + i * 8); } }
