    for (let i = 0; i < 4; i++) { const a = .2 + i * .08, u = ph(t, a, a + .35); if (u > 0 && u < 1) { const p = arcP({ x: M.x, y: M.y }, { x: FXc, y: GY - 4 }, 20, u); disc(g, p.x, p.y, 2, '#3a2a10'); disc(g, p.x, p.y, 1, '#8ad84a'); } }
