    const e = ph(t, 1.2, 2.0); if (e > 0 && e < 1) { for (let i = 0; i < 14; i++) { const a = -3.1 + hash(i) * 3.1; puff(g, TG.x - 28 + Math.cos(a) * 44 * easeO(e), GY - 20 + Math.sin(a) * 36 * easeO(e) + 14 * e * e, 6 + 4 * hash(i + 2), i % 2 ? '#ffffff' : '#d8ecff', .85 * (1 - e)); spr(g, 'icicle', TG.x - 28 + Math.cos(a) * 36 * e, GY - 24 + Math.sin(a) * 30 * e + 20 * e * e, 11, a + e * 6, 1 - e); } bam(g, TG.x - 30, 78, e, '#e8fbff', '#9fe8ff', 34); ring(g, TG.x - 28, GY - 1, e, '#fff', '#9fe8ff', 56); }
