  const slug = s => s.toLowerCase().replace(/[^a-z]/g, '');
  const EFF = {}; for (const e of FXL) EFF[slug(e.name)] = e;
  function run(layer, e, g, mt, S) { const fn = e[layer]; if (!fn) return; try { g.save(); g.imageSmoothingEnabled = false; fn(g, mt, S); } catch (err) { if (!run.warned) { run.warned = 1; console.error('sigfx', e.name, err); } } finally { g.restore(); } }
  return {
    init(imgs) { IM = imgs; },
    has: id => !!EFF[id],
    // c = { x, gy, dir, S, dx (caster travel since cast, mockup px), cdy (caster height gained), lift, tx, ty (foe at cast), fdx, fdy (foe displacement now), img/imgW/imgH (caster sprite), fimg/fimgW/fimgH (foe sprite) }
    move(layer, id, g, mt, c) {
      const e = EFF[id]; if (!e) return;
      ME.img = c.img || null; ME.w = c.imgW || 64; ME.h = c.imgH || 64; FOE.img = c.fimg || null; FOE.w = c.fimgW || 57; FOE.h = c.fimgH || 63;
      TG.x = 50 + Math.max(60, Math.abs(c.tx - c.x) / c.S); TG.y = 108 - ((c.gy - c.lift) - c.ty) / c.S; GY = 108 + c.lift / c.S; M.x = 80; M.y = 74; FXc = TG.x - 6; FYc = TG.y;
      const S = { A: { dx: c.dx || 0, dy: -(c.cdy || 0), a: 1 }, T: { dx: c.fdx || 0, dy: c.fdy || 0, a: 1, hurt: false, rot: 0 }, loop: 0 };
      g.save(); g.translate(c.x, c.gy - c.lift); g.scale(c.dir * c.S, c.S); g.translate(-50, -108); run(layer, e, g, mt, S); g.restore();
    },
  };
